import type { Media, Project, Testimonial } from "../../lib/cms/types";

/**
 * DEMO CONTENT — fictional clients, people, results and quotes, used only in demo mode
 * (lib/demo.ts). None of these companies or people are real. Media is generated by
 * `npm run demo:media` into public/demo/.
 */

const img = (path: string, alt: string, width = 1600, height = 1000): Media => ({
  kind: "image",
  url: `/demo/${path}`,
  alt,
  width,
  height,
});
const vid = (slug: string, alt: string): Media => ({
  kind: "video",
  url: `/demo/projects/${slug}/loop.webm`,
  poster: `/demo/projects/${slug}/loop-poster.webp`,
  alt,
});

