const t = (slug: string) => demoTestimonials.find((x) => x.projectSlug === slug) ?? null;

function project(
  p: Omit<Project, "hero" | "preview" | "design" | "motion" | "testimonial" | "placeholder"> & {
    designText: string[];
    shots: string[];
  },
): Project {
  const { designText, shots, ...rest } = p;
  return {
    ...rest,
    hero: img(`projects/${p.slug}/hero.webp`, `${p.client} — ${p.title}`),
    preview: vid(p.slug, `${p.client}: interface in motion`),
    design: {
      text: designText,
      media: shots.map((alt, i) => img(`projects/${p.slug}/screen-${i + 1}.webp`, alt)),
    },
    motion: [vid(p.slug, `${p.client}: interface in motion`)],
    testimonial: t(p.slug),
    placeholder: false,
  };
}

